// FishMon 365 — lógica de interfaz, simulación, gráficas, profundidad y alertas.
// IMPORTANTE: esta versión usa datos sintéticos de demostración. No recibe datos del hardware.
const DEVICE_IMAGE = "data:image/jpeg;base64,";

const metricConfig = {
  do:{label:"Oxígeno disuelto",unit:"mg/L",min:6,max:8.5,decimals:1,base:7.4,step:.12},
  temp:{label:"Temperatura",unit:"°C",min:9,max:14,decimals:1,base:11.8,step:.16},
  ph:{label:"pH",unit:"pH",min:6.5,max:8,decimals:1,base:7.1,step:.05},
  turbidity:{label:"Turbidez",unit:"NTU",min:5,max:20,decimals:0,base:12,step:.8},
  conductivity:{label:"Conductividad",unit:"μS/cm",min:20,max:500,decimals:0,base:240,step:5}
};
const depthConfig = {surface:{label:"Superficie",factor:.10},middle:{label:"Media agua",factor:.50},bottom:{label:"Fondo",factor:.80}};
let totalDepth=3, selectedDepth="middle", paused=false, intervalMs=5000, timer=null, battery=86;
let current={surface:{},middle:{},bottom:{}}, history={surface:{},middle:{},bottom:{}}, eventLog=[];
let normalCount=0, lastStatuses={}, lastAlarmAt={};

const $=id=>document.getElementById(id);
const fmt=(v,k)=>Number(v).toFixed(metricConfig[k].decimals);
const nowTime=()=>new Date().toLocaleTimeString("es-PE",{hour12:false});
const stamp=()=>new Date().toLocaleString("es-PE",{hour12:false});
const depthValue=key=>key==="surface"?Math.min(.30,totalDepth*.10):totalDepth*depthConfig[key].factor;

function calculateDepths(){
  const input=parseFloat($("totalDepth").value);
  if(!Number.isFinite(input)||input<.5||input>100){toast("Profundidad no válida","Introduce un valor entre 0.5 y 100 metros.");return;}
  totalDepth=input;
  const z1=depthValue("surface"),z2=depthValue("middle"),z3=depthValue("bottom");
  $("calcZ1").textContent=z1.toFixed(2)+" m";$("calcZ2").textContent=z2.toFixed(2)+" m";$("calcZ3").textContent=z3.toFixed(2)+" m";
  $("z1Label").textContent=z1.toFixed(2)+" m";$("z2Label").textContent=z2.toFixed(2)+" m";$("z3Label").textContent=z3.toFixed(2)+" m";
  $("totalDepthLabel").textContent=totalDepth.toFixed(2)+" m";
  $("systemDepth").value=totalDepth.toFixed(1);
  renderDepthTable();renderComparison();updateDepthTop();
  toast("Niveles calculados","Superficie, media agua y fondo actualizados automáticamente.");
}
function seededValue(key,depth){
  const base=metricConfig[key].base;
  const adjustment=depth==="surface"?(key==="do"?.45:key==="temp"?.3:key==="turbidity"?-1:0):depth==="bottom"?(key==="do"?-.75:key==="temp"?-.25:key==="turbidity"?2:0):0;
  return base+adjustment+(Math.random()-.5)*metricConfig[key].step*2;
}
function statusOf(key,value){
  const c=metricConfig[key];
  if(value<c.min*.93||value>c.max*1.07)return "critical";
  if(value<c.min||value>c.max)return "warning";
  return "good";
}
function statusText(s){return s==="critical"?"Crítico":s==="warning"?"Advertencia":"Óptimo";}
function initialize(){
  Object.keys(depthConfig).forEach(d=>{
    Object.keys(metricConfig).forEach(k=>{
      current[d][k]=seededValue(k,d);
      history[d][k]=Array.from({length:18},(_,i)=>current[d][k]+(Math.random()-.5)*metricConfig[k].step*8);
    });
  });
  calculateDepths();renderAll();addEvent("normal","Sistema iniciado","Datos de demostración cargados","—","Sistema");
  $("devicePhoto").src=DEVICE_IMAGE;
  updateClock();setInterval(updateClock,1000);startTimer();
}
function updateClock(){$("clock").textContent=nowTime();}
function startTimer(){if(timer)clearInterval(timer);timer=setInterval(tick,intervalMs);}
function tick(){
  if(paused)return;
  Object.keys(depthConfig).forEach(d=>{
    Object.keys(metricConfig).forEach(k=>{
      const c=metricConfig[k],old=current[d][k];
      let next=old+(Math.random()-.49)*c.step*2.3;
      if(Math.random()<.035)next+=(Math.random()-.5)*c.step*13;
      current[d][k]=Math.max(0,next);
      history[d][k].push(next);if(history[d][k].length>30)history[d][k].shift();
      const s=statusOf(k,next),key=d+"-"+k;
      if(s!=="good"&&lastStatuses[key]!==s){
        const severity=s==="critical"?"critical":"warning";
        addEvent(severity,c.label+" fuera de rango",fmt(next,k)+" "+c.unit,depthConfig[d].label,d);
        showAlarm(c.label,next,k,d,severity);
      }
      lastStatuses[key]=s;
    });
  });
  battery=Math.max(10,battery-(Math.random()<.07?.1:0));
  $("batteryText").textContent=Math.round(battery)+"%";$("batteryBar").style.width=battery+"%";$("systemBattery").textContent=Math.round(battery)+"%";
  $("lastUpdate").textContent=nowTime();$("refreshLabel").textContent="Actualizado "+nowTime();
  renderAll();
}
function renderAll(){renderMetrics();renderSparks();renderMainChart();renderRecentTable();renderDepthTable();renderComparison();renderAlertSummary();updateDepthTop();updateOverall();}
function renderMetrics(){
  const d=selectedDepth;
  Object.keys(metricConfig).forEach(k=>{
    const c=metricConfig[k],v=current[d][k],s=statusOf(k,v);
    $("value-"+k).textContent=fmt(v,k);
    $("status-"+k).textContent=statusText(s);
    $("status-"+k).className="status-badge "+s;
    $("range-"+k).textContent=c.min+"–"+c.max+" "+(k==="ph"?"":c.unit);
    const card=document.querySelector('[data-metric="'+k+'"]');
    card.classList.toggle("warning",s==="warning");card.classList.toggle("critical",s==="critical");
    const arr=history[d][k],delta=arr[arr.length-1]-arr[Math.max(0,arr.length-5)];
    $("trend-"+k).textContent=Math.abs(delta)<c.step*.5?"→ Estable":(delta>0?"↗ +":"↘ −")+fmt(Math.abs(delta),k)+" "+c.unit;
  });
}
function sparkSvg(values,color="#1688c7"){
  const min=Math.min(...values),max=Math.max(...values),range=max-min||1;
  const pts=values.map((v,i)=>`${(i/(values.length-1))*150},${36-((v-min)/range)*28}`).join(" ");
  return `<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>`;
}
function renderSparks(){Object.keys(metricConfig).forEach(k=>{$("spark-"+k).innerHTML=sparkSvg(history[selectedDepth][k]);});}
function chartSvg(series,colors,labels,viewW=720,viewH=230,referenceRange=null){
  const left=42,right=12,top=12,bottom=22,w=viewW-left-right,h=viewH-top-bottom;
  const all=series.flat();
  const rawMin=Math.min(...all),rawMax=Math.max(...all);
  const min=referenceRange?Math.min(rawMin,referenceRange[0]):rawMin;
  const max=referenceRange?Math.max(rawMax,referenceRange[1]):rawMax;
  const pad=(max-min||1)*.2,lo=min-pad,hi=max+pad;
  let html="";
  for(let i=0;i<5;i++){let y=top+h*i/4;html+=`<line x1="${left}" y1="${y}" x2="${viewW-right}" y2="${y}" stroke="#e9eef1" stroke-dasharray="3 4"/><text x="0" y="${y+3}" fill="#9aa6ad" font-size="9">${(hi-(hi-lo)*i/4).toFixed(1)}</text>`;}
  if(referenceRange){
    referenceRange.forEach((v,i)=>{
      const y=top+h-(v-lo)/(hi-lo)*h;
      html+=`<line x1="${left}" y1="${y}" x2="${viewW-right}" y2="${y}" stroke="#d89a24" stroke-width="1.4" stroke-dasharray="6 4"/><text x="${viewW-right-2}" y="${y-4}" text-anchor="end" fill="#b07b18" font-size="8">${i===0?"Límite mínimo":"Límite máximo"} · ${v}</text>`;
    });
  }
  series.forEach((arr,j)=>{
    const points=arr.map((v,i)=>`${left+i/(arr.length-1)*w},${top+h-(v-lo)/(hi-lo)*h}`).join(" ");
    html+=`<polyline points="${points}" fill="none" stroke="${colors[j]}" stroke-width="${j===0?2.8:2.3}" stroke-linecap="round" stroke-linejoin="round"/>`;
    const last=arr[arr.length-1],cx=left+w,cy=top+h-(last-lo)/(hi-lo)*h;
    html+=`<circle cx="${cx}" cy="${cy}" r="4" fill="${colors[j]}" stroke="white" stroke-width="2"/>`;
  });
  return html;
}
function renderMainChart(){
  const k=$("trendMetric").value,arr=history[selectedDepth][k];
  $("trendLegend").textContent=metricConfig[k].label;
  $("mainChart").innerHTML=chartSvg([arr],["#1688c7"],[],720,230,[metricConfig[k].min,metricConfig[k].max]);
}
function renderComparison(){
  const k=$("compareMetric").value;
  $("compareChart").innerHTML=chartSvg(["surface","middle","bottom"].map(d=>history[d][k]),["#1688c7","#e9b900","#1b9b9a"],[],900,300,[metricConfig[k].min,metricConfig[k].max]);
}
function renderRecentTable(){
  const rows=[];
  for(let i=0;i<5;i++){
    const d=selectedDepth,offset=4-i;
    rows.push(`<tr><td>${new Date(Date.now()-offset*intervalMs).toLocaleTimeString("es-PE",{hour12:false})}</td><td>${depthConfig[d].label} · ${depthValue(d).toFixed(2)} m</td><td>${fmt(current[d].do-(Math.random()-.5)*.08,"do")} mg/L</td><td>${fmt(current[d].temp,"temp")} °C</td><td>${fmt(current[d].ph,"ph")}</td><td>${fmt(current[d].turbidity,"turbidity")} NTU</td><td>${fmt(current[d].conductivity,"conductivity")} μS/cm</td><td><span class="table-status ${statusOf("do",current[d].do)}">${statusText(statusOf("do",current[d].do))}</span></td></tr>`);
  }
  $("recentTable").innerHTML=rows.join("");
}
function renderDepthTable(){
  $("depthTable").innerHTML=["surface","middle","bottom"].map(d=>`<tr><td><strong>${depthConfig[d].label}</strong></td><td>${depthValue(d).toFixed(2)} m</td><td>${fmt(current[d].do,"do")}</td><td>${fmt(current[d].temp,"temp")}</td><td>${fmt(current[d].ph,"ph")}</td><td>${fmt(current[d].turbidity,"turbidity")}</td><td>${fmt(current[d].conductivity,"conductivity")}</td></tr>`).join("");
}
function updateDepthTop(){
  $("activeDepthTop").innerHTML=depthValue(selectedDepth).toFixed(2)+' <i>m</i>';
  $("activeDepthName").textContent=depthConfig[selectedDepth].label;
  $("depthNow").textContent=depthValue(selectedDepth).toFixed(2)+" m";
  document.querySelectorAll(".depth-line").forEach((el,i)=>el.classList.toggle("active",["surface","middle","bottom"][i]===selectedDepth));
}
function updateOverall(){
  let worst="good";
  Object.keys(metricConfig).forEach(k=>{const s=statusOf(k,current[selectedDepth][k]);if(s==="critical"||(s==="warning"&&worst==="good"))worst=s;});
  $("overallStatus").textContent=worst==="critical"?"Atención: condición crítica":worst==="warning"?"Revisar parámetros":"Condiciones estables";
  $("overallDescription").textContent=worst==="good"?"Parámetros dentro de los rangos configurados":"Se detectó al menos un parámetro fuera del rango de referencia";
  $("overallStatus").style.color=worst==="critical"?"#d94a4a":worst==="warning"?"#c18418":"#169b68";
  $("activeAlertsTop").textContent=eventLog.filter(e=>e.severity!=="normal").length;
  $("alertStatusText").textContent=worst==="good"?"Sin alertas activas":"Requiere revisión";
}
function addEvent(severity,title,value,depth,location){
  const e={severity,title,value,depth,location,time:stamp()};
  eventLog.unshift(e);if(eventLog.length>100)eventLog.pop();
  if(severity==="normal")normalCount++;
  renderAlertList();renderAlertSummary();
  $("alertCount").textContent=eventLog.filter(x=>x.severity!=="normal").length;
}
function renderAlertList(){
  const filter=$("alertFilter").value;
  const entries=eventLog.filter(e=>filter==="all"||e.severity===filter);
  $("eventTotal").textContent=entries.length+" eventos";
  $("alertList").innerHTML=entries.length?entries.map(e=>`<div class="alert-row"><span class="alert-row-icon ${e.severity}">${e.severity==="critical"?"!":e.severity==="warning"?"△":"✓"}</span><span><strong>${e.title}</strong><small>${e.location==="Sistema"?"Sistema":e.depth+" · "+e.location}</small></span><span class="alert-value">${e.value}</span><time>${e.time}</time><span class="alert-level ${e.severity}">${statusText(e.severity)}</span></div>`).join(""):'<p class="empty-state">No hay eventos para este filtro.</p>';
}
function renderAlertSummary(){
  $("criticalCount").textContent=eventLog.filter(e=>e.severity==="critical").length;
  $("warningCount").textContent=eventLog.filter(e=>e.severity==="warning").length;
  $("normalCount").textContent=normalCount;
}
function showAlarm(label,value,key,depth,severity){
  const id=depth+"-"+key,now=Date.now();
  if(lastAlarmAt[id]&&now-lastAlarmAt[id]<15000)return;
  lastAlarmAt[id]=now;
  $("alarmTitle").textContent=severity==="critical"?"ALERTA CRÍTICA · "+label:"ADVERTENCIA · "+label;
  $("alarmMessage").textContent=depthConfig[depth].label+" ("+depthValue(depth).toFixed(2)+" m): valor "+fmt(value,key)+" "+metricConfig[key].unit+". Revisa los límites configurados.";
  $("alarmOverlay").classList.add("show");
  toast("Alerta de "+statusText(severity).toLowerCase(),label+" fuera del rango de referencia.");
  if("Notification" in window && Notification.permission==="granted"){
    new Notification("FishMon 365 · "+statusText(severity),{body:label+" · "+depthConfig[depth].label+" ("+depthValue(depth).toFixed(2)+" m): "+fmt(value,key)+" "+metricConfig[key].unit,tag:id});
  }
}
function toast(title,message){
  const el=document.createElement("div");el.className="toast";el.innerHTML=`<strong>${title}</strong>${message}`;
  $("toastStack").appendChild(el);setTimeout(()=>el.remove(),5200);
}
function renderThresholds(){
  $("thresholdGrid").innerHTML=Object.entries(metricConfig).map(([k,c])=>`<div class="threshold-item"><label>${c.label} <span style="color:#9ba5ab;font-weight:400">(${c.unit})</span></label><div class="threshold-inputs"><input type="number" step="any" id="min-${k}" value="${c.min}" aria-label="Mínimo ${c.label}"><span>–</span><input type="number" step="any" id="max-${k}" value="${c.max}" aria-label="Máximo ${c.label}"></div></div>`).join("");
  Object.keys(metricConfig).forEach(k=>{
    ["min","max"].forEach(edge=>$(`${edge}-${k}`).addEventListener("change",()=>{
      const lo=parseFloat($("min-"+k).value),hi=parseFloat($("max-"+k).value);
      if(Number.isFinite(lo)&&Number.isFinite(hi)&&lo<hi){metricConfig[k].min=lo;metricConfig[k].max=hi;renderAll();toast("Límites actualizados",metricConfig[k].label+" · "+lo+" a "+hi+" "+metricConfig[k].unit);}
      else toast("Límites no válidos","El mínimo debe ser menor que el máximo.");
    }));
  });
}
function switchView(view){
  document.querySelectorAll(".view-panel").forEach(p=>p.classList.toggle("active",p.id==="view-"+view));
  document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===view));
  const names={dashboard:"Dashboard general",depth:"Monitoreo por profundidad",alerts:"Alertas e historial",system:"Estado del sistema"};
  $("breadcrumbCurrent").textContent=names[view];
  $("pageTitle").textContent=({dashboard:"Calidad del agua",depth:"Monitoreo multinivel",alerts:"Alertas e historial",system:"Estado del sistema"})[view];
  $("pageSubtitle").textContent=({dashboard:"Supervisión inteligente de las condiciones del estanque en tiempo real.",depth:"Compara las mediciones y calcula automáticamente la posición del sensor.",alerts:"Identifica eventos y administra los límites de referencia.",system:"Supervisa los módulos, la alimentación y la arquitectura del dispositivo."})[view];
  $("sidebar").classList.remove("open");
  if(view==="alerts"){renderAlertList();renderThresholds();}
  if(view==="depth"){renderDepthTable();renderComparison();}
}
document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>switchView(b.dataset.view)));
document.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>switchView(b.dataset.go)));
$("depthSelect").addEventListener("change",e=>{selectedDepth=e.target.value;$("quickDepth").value=selectedDepth;renderAll();});
$("quickDepth").addEventListener("change",e=>{selectedDepth=e.target.value;$("depthSelect").value=selectedDepth;renderAll();});
$("trendMetric").addEventListener("change",renderMainChart);
$("compareMetric").addEventListener("change",renderComparison);
$("calculateDepths").addEventListener("click",calculateDepths);
$("totalDepth").addEventListener("keydown",e=>{if(e.key==="Enter")calculateDepths();});
$("systemDepth").addEventListener("change",()=>{$("totalDepth").value=$("systemDepth").value;});
$("saveSettings").addEventListener("click",()=>{
  $("totalDepth").value=$("systemDepth").value;calculateDepths();
  intervalMs=Number($("updateInterval").value)*1000;startTimer();
  $("settingsMessage").textContent="Configuración aplicada localmente · "+nowTime();
});
$("notificationButton").addEventListener("click",async()=>{
  if(!("Notification" in window)){toast("Notificaciones no disponibles","Este navegador no permite notificaciones de escritorio.");return;}
  const permission=await Notification.requestPermission();
  if(permission==="granted"){toast("Notificaciones activadas","Las alertas aparecerán también como notificaciones del navegador mientras la plataforma esté abierta.");$("notificationButton").innerHTML="✓ <span>Alarmas activadas</span>";}
  else toast("Permiso no concedido","Puedes activar las notificaciones desde los permisos del navegador.");
});
$("pauseButton").addEventListener("click",()=>{
  paused=!paused;$("pauseButton").innerHTML=paused?"▶ <span>Reanudar simulación</span>":"Ⅱ <span>Pausar simulación</span>";
  $("refreshLabel").textContent=paused?"En pausa":"Actualizando";toast(paused?"Simulación pausada":"Simulación reanudada",paused?"Las lecturas ya no cambiarán.":"Las lecturas volverán a actualizarse.");
});
$("alertFilter").addEventListener("change",renderAlertList);
$("clearAlerts").addEventListener("click",()=>{eventLog=[];normalCount=0;renderAlertList();renderAlertSummary();updateOverall();$("alertCount").textContent="0";toast("Historial limpiado","Se borraron los eventos de esta sesión de demostración.");});
$("dismissAlarm").addEventListener("click",()=>$("alarmOverlay").classList.remove("show"));
$("themeToggle").addEventListener("click",()=>document.body.classList.toggle("dark-mode"));
$("mobileMenu").addEventListener("click",()=>$("sidebar").classList.toggle("open"));
$("exportButton").addEventListener("click",exportCSV);
function exportCSV(){
  const rows=[["fecha_hora","profundidad","profundidad_m","oxigeno_mg_l","temperatura_c","ph","turbidez_ntu","conductividad_us_cm"]];
  ["surface","middle","bottom"].forEach(d=>rows.push([stamp(),depthConfig[d].label,depthValue(d).toFixed(2),...["do","temp","ph","turbidity","conductivity"].map(k=>fmt(current[d][k],k))]));
  const csv="\uFEFF"+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(";")).join("\n");
  const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"}),url=URL.createObjectURL(blob),a=document.createElement("a");
  a.href=url;a.download="fishmon365-mediciones-demo.csv";a.click();URL.revokeObjectURL(url);
  toast("Exportación preparada","Se descargó el CSV con las mediciones actuales de demostración.");
}
initialize();
